CREATE TABLE IF NOT EXISTS user_listen_logs (id BIGSERIAL PRIMARY KEY, uid TEXT NOT NULL, story_id TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', listen_date DATE NOT NULL, duration_s INT NOT NULL DEFAULT 0, completed BOOLEAN NOT NULL DEFAULT FALSE, tags TEXT[] NOT NULL DEFAULT '{}', age_group TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_user_listen_uid_date ON user_listen_logs (uid, listen_date DESC); CREATE INDEX IF NOT EXISTS idx_user_listen_uid_story ON user_listen_logs (uid, story_id);
